import { TestBed } from '@angular/core/testing';
import { Router } from '@angular/router';
import { BehaviorSubject, of } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { HomeComponent } from './home.component';

describe('HomeComponent', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('goes once to the home of the current language and tenant', () => {
    const language = new BehaviorSubject('en');
    const router = jasmine.createSpyObj<Router>('Router', ['navigate']);
    TestBed.configureTestingModule({
      imports: [HomeComponent],
      providers: [
        { provide: Router, useValue: router },
        { provide: AppStateService, useValue: { language$: language, tenant$: of('acme') } },
      ],
    });

    TestBed.createComponent(HomeComponent);
    language.next('fr');

    expect(router.navigate).toHaveBeenCalledOnceWith(['en', 'acme']);
  });
});
